	if (
		expectedRuns.size !== 0 ||
		behaviors.size !== 1 ||
		receipt.mutation?.intendedFailure !== true ||
		receipt.mutation.failure !== 'witness-semantic-assertion' ||
		receipt.mutation.lane !== 'migrated' ||
